choose.when:

  @("{{billing-base-url}}/api/accounts/by-client/" + (string)context.Variables["clientId"])
  GET

    {{billing-func-key}}






      application/json
      {"error":{"code":"NotOnboarded","message":"This application is not registered with the AI gateway. Contact the AI platform team."}}





      5
      application/json
      {"error":{"code":"BillingUnavailable","message":"The balance check failed. Retry in a few seconds."}}



<set-variable name="acct" value="@(((IResponse)context.Variables["acctResp"]).Body.As())" />

when.log-to-eventhub:
@{
          var body = context.Response.Body.As(preserveContent: true);
          var usage = body["usage"];
          return new JObject(
            new JProperty("chargeId", context.RequestId.ToString()),
            new JProperty("accountId", (string)context.Variables["accountId"]),
            new JProperty("clientId", (string)context.Variables["clientId"]),
            new JProperty("model", (string)body["model"]),
            new JProperty("promptTokens", usage?["prompt_tokens"]?.Value() ?? 0),
            new JProperty("cachedTokens", usage?["prompt_tokens_details"]?["cached_tokens"]?.Value() ?? 0),
            new JProperty("completionTokens", usage?["completion_tokens"]?.Value() ?? 0),
            new JProperty("estimated", false),
            new JProperty("ts", DateTime.UtcNow.ToString("o"))
          ).ToString();
        }

@{
          return new JObject(
            new JProperty("chargeId", context.RequestId.ToString()),
            new JProperty("accountId", (string)context.Variables["accountId"]),
            new JProperty("clientId", (string)context.Variables["clientId"]),
            new JProperty("model", context.Request.MatchedParameters.GetValueOrDefault("deployment-id", "unknown")),
            new JProperty("promptTokens", 0),
            new JProperty("cachedTokens", 0),
            new JProperty("completionTokens", context.Variables.GetValueOrDefault("tokensConsumed", 0)),
            new JProperty("estimated", true),
            new JProperty("ts", DateTime.UtcNow.ToString("o"))
          ).ToString();
        }
